INSERT INTO recipes (title, creator_id, image, portions, ingredients, spices, steps, created)
VALUES (
        "Quinoa Vegetable Stew",
        2,
        "1.jpg",
        4,
        '[{"name":"quinoa","quantity":200,"unit":"gr"},{"name":"peppers","quantity":3,"unit":""},{"name":"carrots","quantity":3,"unit":""},{"name":"onions","quantity":2,"unit":""}]',
        '[{"name":"black pepper","quantity":2,"unit":"ts"},{"name":"salt","quantity":2,"unit":"ts"},{"name":"coriander","quantity":3,"unit":"ts"}]',
        '["Bring water, quinoa, and 1 pinch salt to a boil in a saucepan.","Reduce heat to medium-low, cover, and simmer until quinoa tender, about 20 minutes.","Drain in mesh strainer; set aside","Meanwhile, heat olive oil in a saucepan over medium heat. Stir in garlic; cook until softens and aroma mellows, about 2 minutes. ","Add bell pepper and corn; cook until pepper softens, about 5 minutes.","Season with oregano, cumin, salt, and black pepper; cook 1 minute more, then stir in cooked quinoa and green onions."]',
        '2025-12-23'
    ), (
        "Very Moist Marble Cake",
        2,
        "2.png",
        3,
        '[{"name":"softened butter","quantity":100,"unit":"gr"},{"name":"large eggs","quantity":3,"unit":""},{"name":"whole milk or semi-skimmed","quantity":200,"unit":"gr"},{"name":"oil","quantity":50,"unit":"gr"},{"name":"heavy whipping cream 30%","quantity":100,"unit":"gr"},{"name":"all-purpose flour","quantity":270,"unit":"gr"},{"name":"baking powder","quantity":2,"unit":"ts"},{"name":"unsweetened cocoa powder","quantity":22,"unit":"gr"}]',
        '[{"name":"granulated sugar","quantity":80,"unit":"gr"},{"name":"salt","quantity":0.5,"unit":"ts"}]',
        '["Preheat the oven to 175° traditional heat. Butter and line a cake tin with baking paper.","In a large container, whisk the softened butter and the two sugars to obtain a creamy texture. Add the eggs and mix to homogenize everything.","Separately, mix the dry ingredients: flour, baking powder and salt.","Separately, mix the wet ingredients: milk, oil, cream and vanilla.","Then add half of the wet ingredients to the large container, then half of the dry ingredients. Finish with the rest of the wet ingredients and the rest of the dry ingredients. Do not overmix the batter (just enough) to preserve the softness of the cake","Divide the dough into two equal parts in two containers: in one of them, incorporate the sifted bitter cocoa and mix. To create the marbled effect in the cake pan: first pour a third of the plain batter then half of the chocolate batter. Then add a third of the plain dough, then the last half of the chocolate dough. Finish with the remaining plain dough.","Bake for about 45 to 55 minutes (this varies a lot depending on the oven). The top of the cake should be golden brown. To find out if it\'s cooked through, insert a wooden skewer: it should come out dry or with a few crumbs. Leave to cool then unmold onto a wire rack."]',
        '2025-12-04'
    ), (
        "Quinoa Salad",
        2,
        "4.png",
        6,
        '[{"name":"quinoa","quantity":200,"unit":"gr"},{"name":"orange juice","quantity":2,"unit":"tbs"},{"name":"red wine vinegar","quantity":0.25,"unit":"cups"},{"name":"garlic","quantity":3,"unit":"none"},{"name":"ginger","quantity":2,"unit":"tbs"},{"name":"extra virgin olive oil","quantity":0.75,"unit":"cups"},{"name":"quinoa","quantity":2,"unit":"cups"},{"name":"red onion","quantity":0.33,"unit":"cups"},{"name":"spinach","quantity":2,"unit":"cups"},{"name":"cucumber","quantity":1,"unit":"none"},{"name":"feta","quantity":0.66,"unit":"cups"}]',
        '[{"name":"curry powder","quantity":2,"unit":"tbs"},{"name":"salt","quantity":1.5,"unit":"tbs"},{"name":"sugar or honey","quantity":1,"unit":"tbs"}]',
        '["Use a blender or food processor to combine all the ingredients except the olive oil. Slowly drizzle the olive oil in as you\'re blending until the dressing emulsifies and becomes creamy in appearance.","Combine the quinoa, red onion, arugula, cashews, cucumber, and chickpeas in a large bowl","Drizzle with about 1/2 cup of the ginger-curry dressing. Toss well, and then toss more","Sprinkle the feta across the salad and gently toss to distribute throughout."]',
        '2025-11-26'
    ), (
       "Baked Quinoa Patties",
        2,
        "5.png",
        12,
        '[{"name":"quinoa","quantity":340,"unit":"gr"},{"name":"eggs","quantity":5,"unit":"none"},{"name":"kale","quantity":1,"unit":"cup"},{"name":"onion","quantity":1,"unit":"none"},{"name":"garlic","quantity":3,"unit":"none"},{"name":"feta","quantity":40,"unit":"gr"},{"name":"extra virgin olive oil","quantity":1,"unit":"tbs"}]',
        '[{"name":"salt","quantity":0.5,"unit":"ts"},{"name":"cumin","quantity":1,"unit":"ts"},{"name":"baking powder","quantity":1,"unit":"ts"}]',
        '["Preheat oven to 400F / 200C.","Combine the quinoa, eggs, and salt in a medium bowl. Stir in the chives, dill, kale, onion, garlic, and cumin. Stir well.","Add the baking powder and bread crumbs, stir, and let sit for a few minutes so the crumbs can absorb some of the moisture. Gently stir in the feta.","At this point, you should have a mixture you can easily form into twelve 1-inch / 2.5cm thick patties. Use about 1/2 cup of the quinoa mixture per patty. I err on the very moist side because it makes for a not-overly-dry patty, but you can add more bread crumbs, a bit at a time, to firm up the mixture, if need be. Conversely, a bit more beaten egg or water can be used to moisten the mixture. If you\'re still having trouble getting the mixture to hold - mix in flour, a couple tablespoons at a time.","Oil a baking sheet, and arrange the patties with a bit of space between each. Sprinkle with sesame seeds if you like. Bake for ~20 minutes, or until the bottoms are brown. Flip and bake for another 5 minutes. Enjoy hot, or allow to cool to room temperature on a cooling rack."]',
        '2025-12-20'
    ), (
        "Gramma\'s Lentil Soup with Garlic Bread",
        2,
        "6.jpg",
        6,
        '[{"name":"oil","quantity":2,"unit":"tbs"},{"name":"onion","quantity":1,"unit":"none"},{"name":"garlic cloves","quantity":3,"unit":"none"},{"name":"carrots","quantity":3,"unit":"none"},{"name":"wine vinegar","quantity":2,"unit":"ts"},{"name":"red lentils","quantity":2,"unit":"cups"},{"name":"can tomatoes","quantity":1,"unit":"none"},{"name":"vegetable stock","quantity":1,"unit":"none"}]',
        '[{"name":"paprika","quantity":1,"unit":"ts"},{"name":"died mixed herbs","quantity":1,"unit":"ts"}]',
        '["Heat the oil in a pan and fry the onions until soft (about 5 minutes).","Add the garlic, leeks, carrots and celery and cook for 5 minutes, stirring occasionally.","Add the paprika, herbs, pepper sauce, vinegar, lentils, tomatoes and stock. Stir well.","Bring to the boil, then reduce heat and simmer for 40-50 minutes, stirring occasionally.","Remove from heat, leave to cool slightly, then liquidise in a food processor or blender, or pass through a large sieve.","Pour back into pan and reheat.","Serve with hot toasted garlic bread."]',
        '2026-01-06'
    ), (
        "Microwaved Quinoa Pilaf",
        2,
        "7.jpg",
        4,
        '[{"name":"red bell pepper","quantity":0.25,"unit":"cups"},{"name":"garlic","quantity":2,"unit":"none"},{"name":"onion","quantity":1,"unit":"none"},{"name":"quinoa","quantity":0.75,"unit":"cups"},{"name":"Vegetable broth","quantity":1.5,"unit":"cups"}]',
        '[{"name":"paprika","quantity":1,"unit":"ts"},{"name":"died mixed herbs","quantity":1,"unit":"ts"}]',
        '["Place pepper, garlic, onion and sesame oil in a 4-cup glass measure.","Microwave uncovered on High for 2 minutes and stir.","Add quinoa and broth and microwave on high for 5 minutes, stirring once.","Microwave on medium (50%) for 15 minutes.","Stir.","Microwave on high another 2 minutes or until liquid is absorbed.","Check that grains are pearly, with white outline visible.","Fluff with a fork."]',
        '2026-01-07'
    ), (
        "Spinach Rice",
        2,
        "8.jpg",
        4,
        '[{"name":"spinach","quantity":500,"unit":"mgr"},{"name":"olive oil","quantity":4,"unit":"tbs"},{"name":"garlic","quantity":2,"unit":"none"},{"name":"lemon zest","quantity":2,"unit":"tbs"},{"name":"onion","quantity":1,"unit":"none"},{"name":"long grain rice","quantity":2,"unit":"cups"},{"name":"stock","quantity":4,"unit":"cups"}]',
        '[{"name":"salt","quantity":1,"unit":"ts"},{"name":"ground pepper","quantity":1,"unit":"ts"}]',
        '["Heat half of the oil over medium heat in a large skillet.","Add the garlic and cook until soft.","Add the spinach and cook until just wilted.","Season with salt and pepper to taste and stir in the lemon zest.","Heat the remaining oil in a medium saucepan over medium heat.","Add the onion and cook until soft.","Add the rice and stir to coat with the oil.","Add the stock, bring to a boil, stir once, cover and cook until done, 12-14 minutes.","Fold the spinach into the rice and serve."]',
        '2025-10-10'
    ), (
