        4,
        '[{"name":"beef round steak","quantity":1000,"unit":"gr"},{"name":"vegetable oil","quantity":1,"unit":"tbs"},{"name":"sesame oil","quantity":1,"unit":"ts"},{"name":"low-sodium soy sauce","quantity":1,"unit":"tbs"},{"name":"celery stalk","quantity":3,"unit":"none"},{"name":"onions","quantity":2,"unit":"none"},{"name":"chicken broth","quantity":1,"unit":"cups"},{"name":"bean sprouts","quantity":2,"unit":"cups"}]',
